export function contract(language) {
  const root = cached('module_function:contracts',
    () => parseLinoRoot(readText('data/meta/function-test-contracts.lino') ?? '').children[0] ?? null);
  return (root?.children || []).find((node) => node.name === 'language' && node.id === language) ?? null;
}

/** The language the seeded extension table names for `path`, or null. */
export function extensionLanguage(path) {
  const table = cached('module_function:extensions', () => {
    const root = parseLinoRoot(readText('data/seed/page-formalization-rules.lino') ?? '').children[0];
    return (root?.children || []).filter((node) => node.name === 'extension')
      .map((node) => [findChildValue(node, 'suffix'), findChildValue(node, 'language')]);
  });
  return table.find(([suffix]) => suffix !== '' && path.endsWith(suffix))?.[1] ?? null;
}

/** The request without its quoted segments. */
function outsideQuotes(request) {
  let outside = '';
  let cursor = 0;
  for (const segment of quotedSegmentSpans(request)) {
    if (segment.start < cursor) continue;
    outside += `${request.slice(cursor, segment.start)} `;
    cursor = segment.end;
  }
  return outside + request.slice(cursor);
}

/** The request's clauses: split at `,` `;` and sentence ends (in any script) outside parentheses. */
function clauses(request) {
  const out = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index < request.length; index += 1) {
    const character = request[index];
    if (character === '(') depth += 1;
    else if (character === ')') depth = Math.max(0, depth - 1);
    else if (depth === 0 && (/[\uff0c\uff1b\u3002\uff01\uff1f\u0964]/u.test(character)
      || (/[,;.!?]/u.test(character) && (index + 1 === request.length || /\s/u.test(request[index + 1]))))) {
      out.push(request.slice(start, index));
      start = index + 1;
    }
  }
  out.push(request.slice(start));
  return out.map((clause) => clause.trim()).filter(Boolean);
}

/** `name(a, b)`: the first call-shaped signature whose parameters are identifiers. */
export function signature(text) {
  for (const match of text.matchAll(/([A-Za-z_$][\w$]*)\s*\(([^()]*)\)/gu)) {
    const parameters = match[2].split(',').map((part) => part.trim());
    if (parameters.every((parameter) => /^[A-Za-z_$][\w$]*$/u.test(parameter))) {
      return { name: match[1], parameters, at: match.index };
    }
  }
  return null;
}

/** The marks that end a command's last word: sentence and clause marks in any script. */
const COMMAND_ENDS = /[,;.!?\uff0c\uff1b\u3002\uff01\uff1f\u0964]$/u;
const COMMAND_PEEL = /[,;.!?\uff0c\uff1b\u3002\uff01\uff1f\u0964]+$/u;

/**
 * The command the request's last seeded run verb names, headed by a seeded
 * shell token: the words after the verb ("run node --test", "запусти node
 * --test", "运行 node --test"), or, in a verb-final clause, the words from the
 * shell token up to the verb ("node --test चलाओ"). A run verb is a seeded
 * `run_verbs` word in any script, or a word ending in a seeded
 * `cjk_run_verbs` verb ("然后运行").
 */
function statedCommand(request) {
  const vocabulary = terminalCommandVocabulary();
  const heads = [...vocabulary.shell_tokens, ...vocabulary.bare_shell_tokens];
  const stops = [...wordsForRole('statement_function_word'), ...wordsForRole('skill_procedure_clause_separator')];
  const words = request.split(/\s+/u).filter(Boolean);
  const runs = (word) => vocabulary.run_verbs.includes(normalizeCommandWord(word)) || vocabulary.run_verbs.includes(bare(word))
    || vocabulary.cjk_run_verbs.some((verb) => bare(word).endsWith(verb));
  let verb = -1;
  words.forEach((word, index) => {
    if (runs(word)) verb = index;
  });
  if (verb < 0) return null;
  const commandFrom = (span) => {
    const command = [];
    for (const word of span) {
      if (stops.includes(bare(word))) break;
      const ends = COMMAND_ENDS.test(word);
      command.push(word.replace(COMMAND_PEEL, ''));
      if (ends) break;
    }
    return command.length && heads.includes(command[0]) ? command.join(' ') : null;
  };
  const after = commandFrom(words.slice(verb + 1));
  if (after !== null) return after;
  const tail = words.slice(verb + 1);
  for (let index = 0; index < tail.length; index += 1) {
    if (heads.includes(tail[index])) return commandFrom(tail.slice(index));
    if (/[.!?\uff01\uff1f\u3002\u0964]$/u.test(tail[index])) break;
  }
  const head = words.slice(0, verb).findLastIndex((word) => heads.includes(word));
  return head < 0 ? null : commandFrom(words.slice(head, verb));
}

/** Mirrors `fn paths_in`: the paths `text` names, each once, in order. */
export function pathsIn(text) {
  return [...new Set(tokens(text).map((token) => cleanPathToken(token.text))
    .filter((path) => looksLikeFilePath(path) && safeRelativePath(path)))];
}

/**
 * The module-function request `task` states, or null: a seeded code construct
 * (`coding_request_object`) the request asks to write or add, a signature,
 * the module it goes in (the first path after the signature whose extension
 * names a language with a test contract), and — when the request names a test
 * (`coding_test_artifact_kind`) — the one other path, the test module.
 */
export function moduleFunctionRequest(task) {
  const outside = outsideQuotes(task);
  const normalized = normalizePrompt(outside).toLowerCase();
  if (!mentionsRole('coding_request_object', normalized)
    || !(mentionsRole('coding_request_verb', normalized) || mentionsRole('coding_member_add_action', normalized))) return null;
  const stated = signature(outside);
  if (!stated) return null;
  const parts = clauses(outside);
  const at = parts.findIndex((part) => signature(part)?.name === stated.name);
  // The module is the path the signature's own clause names, before or after
  // it ("math.mjs में एक फ़ंक्शन f(a, b) जोड़ो"); otherwise the first path
  // after the signature.
  const own = at < 0 ? [] : pathsIn(parts[at]);
  const paths = own.length === 1
    ? [own[0], ...pathsIn(outside).filter((path) => path !== own[0])]
    : pathsIn(outside.slice(stated.at));
  const module = paths[0];
  const language = module === undefined ? null : extensionLanguage(module);
  if (language === null || contract(language) === null || !programLanguageBySlug(language)) return null;
  const others = paths.slice(1);
  const wantsTest = mentionsRole('coding_test_artifact_kind', normalized);
  if (others.length > 1 || (wantsTest && others.length !== 1) || (!wantsTest && others.length)) return null;
  // The specification is the signature's clause, joined by the relative
  // clause right after it when the return is stated there ("…, которая
  // возвращает их сумму").
  const returnsIn = (part) => part.split(/\s+/u).some((word) => mentionsRole('coding_return_action', bare(word)));
  const relative = at >= 0 && !returnsIn(parts[at]) && at + 1 < parts.length && returnsIn(parts[at + 1]);
  const clause = at < 0 ? outside : relative ? `${parts[at]} ${parts[at + 1]}` : parts[at];
  return { ...stated, module, test: others[0] ?? null, language, clause, command: statedCommand(outside) };
}


/** Mirrors fn observed_callable_request: declaration-scoped operands, never an implementation. */
export function observedCallableRequest(task) {
  const outside = outsideQuotes(task), parts = clauses(outside), stated = signature(outside);
  if (stated === null) return null;
  const at = parts.findIndex((part) => signature(part)?.name === stated.name);
  if (at < 0) return null;
  const authoring = (part) => {
    const normalized = normalizePrompt(part).toLowerCase();
    return mentionsRole('coding_request_verb', normalized) || mentionsRole('coding_member_add_action', normalized);
  };
  let declaration = parts[at];
  if (!authoring(declaration)) {
    const previous = parts[at - 1];
    if (previous === undefined || !authoring(previous)
      || !mentionsRole('coding-source-artifact-kind', normalizePrompt(previous).toLowerCase())) return null;
    declaration = previous;
  }
  const own = pathsIn(declaration);
  if (own.length !== 1 || extensionLanguage(own[0]) === null) return null;
  const command = statedCommand(outside), acceptance = command === null ? [] : pathsIn(command);
  if (acceptance.includes(own[0])) return null;
  const inputs = pathsIn(outside).filter((path) => path !== own[0] && !acceptance.includes(path));
  if (inputs.length === 0 || !mentionsRole('file_read_action_cue', normalizePrompt(outside).toLowerCase())) return null;
  return { name: stated.name, parameters: stated.parameters, destination: own[0], inputs, acceptance, command };
}

/**
 * The binary operations the seed relates to a named arithmetic relation: each
 * `coding_fragment` of data/seed/coding-composition-fragments.lino whose idiom
 * is `{left} <operator> {right}`, with the reductions it `supports`
 * (`integer_add` supports `reduce_sum`, `integer_multiply` `reduce_product`).
 */
function relationOperations() {
  return cached('module_function:relations', () => {
    const root = parseLinoRoot(readText('data/seed/coding-composition-fragments.lino') ?? '').children[0];
    return (root?.children || []).map((node) => ({
      idiom: findChildValue(node, 'idiom'),
      supports: (node.children || []).filter((child) => child.name === 'supports').map((child) => String(child.id ?? child.value ?? '')),
      // The realization per language (the Python idiom is the canonical
      // surface) and whether the typed signature takes integers.
      realizations: Object.fromEntries((node.children || []).filter((child) => child.name === 'realization')
        .flatMap((child) => child.children || []).map((child) => [child.name, String(child.value ?? '')])),
      integer: findChildValue(node, 'fragment_signature').replace(/[()]/gu, '').split(/\s+/u)
        .every((type) => type === 'integer'),
    })).filter(({ idiom }) => /^\{left\} \S+ \{right\}$/u.test(idiom));
  });
}

/**
 * `left <operator> right` for the one arithmetic relation `text` names in any
 * seeded language ("their sum", "их сумму", "उनका योग", "它们的乘积"), or
 * null when it names none or several.
 */
function relationExpression(text, samples) {
  if (samples.length !== 2) return null;
  const normalized = normalizePrompt(text).toLowerCase();
  const named = relationOperations()
    .filter(({ supports }) => supports.some((relation) => meaningEvidencedIn(relation, normalized)));
  return named.length === 1 ? fill(named[0].idiom, [['left', samples[0]], ['right', samples[1]]]) : null;
}

/** The calculator's value of `expression`, or null. */
function evaluated(expression) {
  try {
    const value = realm().evaluateArithmetic(expression);
    return value === null || value === undefined ? null : String(value);
  } catch {
    return null;
  }
}

/**
 * The specification's value at `samples`, computed by the calculator, or
 * null: the clause after the seeded return action with the parameters bound
 * to the samples ("a times b" -> "2 times 3"), or, when that names no
 * operands, the arithmetic relation the clause names around its return
 * action applied to the samples in parameter order ("returns their sum" ->
 * "2 + 3"; the relation can precede the verb, as in "उनका योग लौटाता है").
 */
function specifiedValue(request, samples) {
  const words = request.clause.split(/\s+/u);
  const returns = words.findIndex((word) => mentionsRole('coding_return_action', bare(word)));
  if (returns < 0) return null;
  const afterSignature = request.clause.slice(request.clause.indexOf(')') + 1);
  return statedValue(words.slice(returns + 1), afterSignature, request.parameters, samples);
}

/**
 * Mirrors `fn stated_value` in rust/src/agentic_coding/module_function.rs: the
 * value a stated return computes at `samples` -- the longest expression the
 * words open with, its parameters bound to the samples ("a - b to m.mjs" ->
 * "2 - 3"; the words after it belong to the request, PR #1188 T92), or else
 * the arithmetic relation `relationText` names applied to the samples.
 */
export function statedValue(words, relationText, parameters, samples) {
  const bound = words.map((word) => {
    const index = parameters.indexOf(bare(word));
    return index < 0 ? word : samples[index];
  });
  for (let end = bound.length; end > 0; end -= 1) {
    const extracted = realm().extractArithmeticExpression(bound.slice(0, end).join(' '));
    if (extracted && extracted.expression) return evaluated(extracted.expression);
  }
  const relation = relationExpression(relationText, samples);
  return relation === null ? null : evaluated(relation);
}

/** The seeded function a language lowers a body into (`{language}_ir_function`), or null. */
function functionTemplate(language) {
  const root = cached('module_function:runtime-templates',
    () => parseLinoRoot(readText('data/seed/coding-discovery-runtime.lino') ?? ''));
  const template = (root.children || []).flatMap((node) => node.children || [])
    .find((node) => node.name === 'template' && String(node.id ?? node.value ?? '') === `${language}_ir_function`);
  return template ? findChildValue(template, 'text') || null : null;
}

/**
 * Mirrors `fn synthesized_source` in rust/src/agentic_coding/module_function.rs:
 * the one seeded integer operation whose idiom meets the specification at
 * every sample pair of the contract, applied to the parameters in order and
 * lowered through the language's function template; null when none or
 * several meet it.
 */
function searchedSource(request, terms) {
  const arity = request.parameters.length;
  const samples = findChildValue(terms, 'samples').split(/\s+/u).filter(Boolean);
  if (arity !== 2 || samples.length < arity) return null;
  const pairs = [];
  for (let index = 0; index + arity <= samples.length; index += arity) pairs.push(samples.slice(index, index + arity));
  const specified = pairs.map((pair) => specifiedValue(request, pair));
  if (specified.some((value) => value === null)) return null;
  const meeting = relationOperations().filter((operation) => operation.integer && pairs.every((pair, index) =>
    evaluated(fill(operation.idiom, [['left', pair[0]], ['right', pair[1]]])) === specified[index]));
  if (meeting.length !== 1) return null;
  const [operation] = meeting;
  const surface = request.language === 'python' ? operation.idiom : operation.realizations[request.language];
  const template = functionTemplate(request.language);
  if (!surface || template === null) return null;
  const expression = fill(surface, [['left', request.parameters[0]], ['right', request.parameters[1]]]);
  return fill(template, [['name', request.name], ['parameters', request.parameters.join(', ')], ['expression', expression]]);
}

/** `source` with `name` imported from `specifier` through the contract's import line. */
function withImport(source, template, name, specifier) {
  const [prefix, suffix] = fill(template, [['specifier', specifier]]).split('{names}');
  const lines = source.split('\n');
  const at = lines.findIndex((line) => line.startsWith(prefix) && line.endsWith(suffix));
  if (at >= 0) {
    const names = lines[at].slice(prefix.length, lines[at].length - suffix.length).split(',').map((part) => part.trim());
    if (!names.includes(name)) lines[at] = `${prefix}${[...names, name].join(', ')}${suffix}`;
    return lines.join('\n');
  }
  const head = prefix.split(/\s/u)[0];
  const last = lines.reduce((found, line, index) => (line.startsWith(head) ? index : found), -1);
  lines.splice(last + 1, 0, `${prefix}${name}${suffix}`);
  return lines.join('\n');
}

/** The import specifier of `module` from a file at `from`, both workspace-relative. */
function specifierFrom(from, module) {
  const base = from.split('/').slice(0, -1);
  const target = module.split('/');
  let shared = 0;
  while (shared < base.length && shared < target.length - 1 && base[shared] === target[shared]) shared += 1;
  const up = base.slice(shared).map(() => '..');
  const path = [...up, ...target.slice(shared)].join('/');
  return up.length ? path : `./${path}`;
}

const withFinalNewline = (text) => (text === '' || text.endsWith('\n') ? text : `${text}\n`);

/** The recipe that adds the function and its test and runs the check, or null. */
async function moduleFunctionRecipe(request, moduleSource, testSource) {
  const terms = contract(request.language);
  const catalog = programLanguageBySlug(request.language);
  // The module is where the function goes and the member-add verb how it
  // gets there, not what it computes: the clause is solved without them, so a
  // path never reads as a page to open and "जोड़ो" (add it) never as a sum.
  const adds = wordsForRole('coding_member_add_action');
  const specification = request.clause.split(request.module).join(' ').split(/\s+/u)
    .filter((word) => word !== '' && !adds.includes(bare(word))).join(' ');
  const answer = await solve(`${specification} ${catalog.name}`, []);
  const program = answer?.synthesized_program;
  // A body stated as an expression ("returns a - b") names no structure the
  // composer can discover; the seeded operation that meets the specification
  // at every sample pair is the function then, as natively (PR #1188 T92).
  const composed = program && program.language === request.language ? program.source : searchedSource(request, terms);
  if (composed === null) return null;
  const definition = fill(findChildValue(terms, 'definition'), [['name', request.name]]);
  const defined = moduleSource.split('\n').some((line) => line.startsWith(definition));
  const source = defined ? moduleSource
    : `${withFinalNewline(moduleSource)}${moduleSource.trim() === '' ? '' : '\n'}${composed}`;
  const commands = [catalog.execution.check_command]
    .filter((command) => command !== null && command !== undefined)
    .map((command) => command.split(catalog.save_as).join(request.module));
  const supporting = [];
  if (request.test !== null) {
    const samples = findChildValue(terms, 'samples').split(/\s+/u).slice(0, request.parameters.length);
    const expected = specifiedValue(request, samples);
    if (expected === null || samples.length !== request.parameters.length) return null;
    const specifier = specifierFrom(request.test, request.module);
    const base = testSource.trim() === '' ? findChildValue(terms, 'header') : withFinalNewline(testSource);
    const imported = withImport(base, findChildValue(terms, 'import'), request.name, specifier);
    const testCase = fill(findChildValue(terms, 'case'),
      [['name', request.name], ['arguments', samples.join(', ')], ['expected', expected]]);
    supporting.push({ path: request.test, source: imported.includes(testCase) ? imported : `${imported}${testCase}` });
  }
  const run = request.command ?? (request.test === null ? null : fill(findChildValue(terms, 'run'), [['test', request.test]]));
  if (run !== null) commands.push(run);
  return { language: request.language, source, path: request.module, supporting_files: supporting, commands };
}

/** The file `path` as the transcript's read returned it; '' for a missing file, null when unread. */
export function readSource(currentTurn, path) {
  const read = resultForPath(currentTurn, Capability.Read, path, null);
  if (read === null) return null;
  const missing = sourceFromAgentReadResult(read) === null && failureMessage(read, false, true) !== null;
  return missing ? '' : sourceFromReadResult(read);
}

/**
 * Plan the next step of a module-function request: read the module and the
 * test module, then hand the computed recipe to the execution-recipe reroute.
 */
export async function planModuleFunctionStep(task, messages, toolNames) {
  const observed = observedCallableRequest(task);
  if (observed !== null) return planObservedCallableStep(observed, messages, toolNames);
  const request = moduleFunctionRequest(task);
  if (!request) return null;
  const currentTurn = messages.slice(evidenceWindowStart(messages));
  const readTool = toolFor(toolNames, Capability.Read);
  const sources = [];
  for (const path of [request.module, request.test].filter((path) => path !== null)) {
    const source = readSource(currentTurn, path);
    if (source === null) return readTool ? planOne(readTool, readArguments(path)) : null;
    sources.push(source);
  }
  const recipe = await moduleFunctionRecipe(request, sources[0], sources[1] ?? '');
  return recipe ? planSymbolicCommandReroute(messages, toolNames, { execution_recipe: recipe }) : null;
}

changes.before:
//! Add a synthesized function to an existing source module, a test of it to
//! its test module, and run the stated command (PR #1188 dogfooding, T1):
//!
//! ```text
//! Add a function multiply(a, b) to math.mjs that returns a times b, add a
//! test for it to math.test.mjs, and run node --test to confirm it passes.
//! ```
//!
//! The native twin of `js/agentic/module_function.mjs`, function by function.
//! Nothing here knows the task. The module's language is the one the seeded
//! extension table of `data/seed/page-formalization-rules.lino` names; the
//! test's expected value is computed from the specification itself -- the
//! clause after the seeded return action, its parameters bound to the
//! contract's sample arguments, or the seeded arithmetic relation it names --
//! evaluated by the calculator, never from the synthesized code. The edits and
//! the command run through the execution-recipe reroute, so the module and the
//! test are written whole after they were read, and the request's own command
//! is the verification.
//!
//! One step differs from the browser root: the JavaScript arm synthesizes the
//! function with the shared solver's browser composer, which the native
//! solver does not have. The native arm searches the seeded binary operations
//! instead (`synthesized_source`): the one whose idiom meets the
//! specification at every sample pair of the contract is lowered through the
//! language's IR lowering (`coding/ir_lowering`).

mod discovery;

use super::final_result::FinalResult;
use super::planner::{AgenticPlan, Capability};
use crate::coding::fragment_catalog::FragmentCatalog;
use crate::coding::program_ir::{IrNode, IrType, ProgramIr, ReuseMode};
use crate::engine::{ExecutionRecipe, ExecutionRecipeFile, SymbolicAnswer};
use crate::protocol::ChatMessage;
use crate::seed::{self, parser::LinoNode, parser::parse_lino};

const CONTRACTS: &str = include_str!("../../embedded/data/meta/function-test-contracts.lino");
const EXTENSIONS: &str = include_str!("../../embedded/data/seed/page-formalization-rules.lino");

/// The marks that end a command's last word: sentence and clause marks in
/// any script. Mirrors `COMMAND_ENDS` in `js/agentic/module_function.mjs`.
const COMMAND_ENDS: [char; 11] = [
    ',', ';', '.', '!', '?', '\u{ff0c}', '\u{ff1b}', '\u{3002}', '\u{ff01}', '\u{ff1f}', '\u{0964}',
];

/// The ideographic and Devanagari marks that end a clause wherever they sit.
const SCRIPT_CLAUSE_MARKS: [char; 6] = [
    '\u{ff0c}', '\u{ff1b}', '\u{3002}', '\u{ff01}', '\u{ff1f}', '\u{0964}',
];

/// A module-function request: the signature, the module it goes in, the test
/// module (when the request names a test), the module's language, the
/// specification clause and the stated command.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModuleFunctionRequest {
    pub name: String,
    pub parameters: Vec<String>,
    pub at: usize,
    pub module: String,
    pub test: Option<String>,
    pub language: String,
    pub clause: String,
    pub command: Option<String>,
}

/// `name(a, b)` and the byte offset it starts at.
pub(super) struct Signature {
    pub(super) name: String,
    pub(super) parameters: Vec<String>,
    pub(super) at: usize,
}

/// The import-line slot the imported names fill.
const NAMES_SLOT: &str = concat!("{", "names", "}");

/// `template` with each `{slot}` replaced. Mirrors `fill`.
fn fill(template: &str, slots: &[(&str, &str)]) -> String {
    slots
        .iter()
        .fold(template.to_owned(), |text, (slot, value)| {
            text.replace(&format!("{{{slot}}}"), value)
        })
}

/// A word without its edge punctuation, lowercased. Mirrors `bare`.
fn bare(word: &str) -> String {
    word.trim_matches(|character: char| !character.is_alphanumeric())
        .to_lowercase()
}

/// The function-test contract of `language`. Mirrors `contract`.
pub(super) fn contract(language: &str) -> Option<LinoNode> {
    let root = parse_lino(CONTRACTS);
    root.children
        .first()?
        .children
        .iter()
        .find(|node| node.name == "language" && node.id == language)
        .cloned()
}

/// The language the seeded extension table names for `path`. Mirrors
/// `extensionLanguage`.
pub(super) fn extension_language(path: &str) -> Option<String> {
    let root = parse_lino(EXTENSIONS);
    root.children
        .first()?
        .children
        .iter()
        .filter(|node| node.name == "extension")
        .find(|node| {
            let suffix = node.find_child_value("suffix");
            !suffix.is_empty() && path.ends_with(suffix)
        })
        .map(|node| node.find_child_value("language").to_owned())
}

/// The request without its quoted segments. Mirrors `outsideQuotes`.
fn outside_quotes(request: &str) -> String {
    let mut outside = String::new();
    let mut cursor = 0;
    for segment in crate::normal_markov::quoted_segment_spans(request) {
        if segment.start < cursor {
            continue;
        }
        outside.push_str(&request[cursor..segment.start]);
        outside.push(' ');
        cursor = segment.end;
    }
    outside.push_str(&request[cursor..]);
    outside
}

/// The request's clauses: split at `,` `;` and sentence ends (in any script)
/// outside parentheses. Mirrors `clauses`.
fn clauses(request: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth: usize = 0;
    let mut start = 0;
    let characters: Vec<(usize, char)> = request.char_indices().collect();
    for (position, (index, character)) in characters.iter().copied().enumerate() {
        if character == '(' {
            depth += 1;
        } else if character == ')' {
            depth = depth.saturating_sub(1);
        } else if depth == 0
            && (SCRIPT_CLAUSE_MARKS.contains(&character)
                || (matches!(character, ',' | ';' | '.' | '!' | '?')
                    && characters
                        .get(position + 1)
                        .is_none_or(|(_, next)| next.is_whitespace())))
        {
            out.push(request[start..index].to_owned());
            start = index + character.len_utf8();
        }
    }
    out.push(request[start..].to_owned());
    out.into_iter()
        .map(|clause| clause.trim().to_owned())
        .filter(|clause| !clause.is_empty())
        .collect()
}

/// Whether `text` is an identifier of the signature grammar (`[A-Za-z_$][\w$]*`).
fn is_identifier(text: &str) -> bool {
    let mut characters = text.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_' || first == '$')
        && characters.all(|character| {
            character.is_ascii_alphanumeric() || character == '_' || character == '$'
        })
}

/// `name(a, b)`: the first call-shaped signature whose parameters are
/// identifiers. Mirrors `signature`.
pub(super) fn signature(text: &str) -> Option<Signature> {
    for (open, _) in text.match_indices('(') {
        let Some(close) = text[open + 1..]
            .find([')', '('])
            .map(|offset| open + 1 + offset)
        else {
            continue;
        };
        if !text[close..].starts_with(')') {
            continue;
        }
        let head = text[..open].trim_end();
        let name_start = head
            .char_indices()
            .rev()
            .take_while(|(_, character)| {
                character.is_ascii_alphanumeric() || *character == '_' || *character == '$'
            })
            .last()
            .map(|(index, _)| index);
        // The name starts at its first letter, `_` or `$`, as the regular
        // expression's leftmost match does ("2both(" names `both`).
        let Some(name_start) = name_start.and_then(|start| {
            head[start..]
                .char_indices()
                .find(|(_, character)| {
                    character.is_ascii_alphabetic() || *character == '_' || *character == '$'
                })
                .map(|(offset, _)| start + offset)
        }) else {
            continue;
        };
        let name = &head[name_start..];
        if !is_identifier(name) {
            continue;
        }
        let parameters: Vec<String> = text[open + 1..close]
            .split(',')
            .map(|part| part.trim().to_owned())
            .collect();
        if parameters.iter().all(|parameter| is_identifier(parameter)) {
            return Some(Signature {
                name: name.to_owned(),
                parameters,
                at: name_start,
            });
        }
    }
    None
}

/// The command the request's last seeded run verb names, headed by a seeded
/// shell token: the words after the verb, or, in a verb-final clause, the
/// words from the shell token up to the verb. Mirrors `statedCommand`.
fn stated_command(request: &str) -> Option<String> {
    let vocabulary = seed::terminal_command_vocabulary();
    let heads: Vec<&String> = vocabulary
        .shell_tokens
        .iter()
        .chain(vocabulary.bare_shell_tokens.iter())
        .collect();
    let lexicon = seed::lexicon();
    let mut stops = lexicon.words_for_role(seed::ROLE_STATEMENT_FUNCTION_WORD);
    stops.extend(lexicon.words_for_role(seed::ROLE_SKILL_PROCEDURE_CLAUSE_SEPARATOR));
    let words: Vec<&str> = request.split_whitespace().collect();
    let runs = |word: &str| {
        let plain = bare(word);
        vocabulary
            .run_verbs
            .contains(&super::shell_command_policy::normalize_command_word(word))
            || vocabulary.run_verbs.contains(&plain)
            || vocabulary
                .cjk_run_verbs
                .iter()
                .any(|verb| plain.ends_with(verb.as_str()))
    };
    let verb = words.iter().rposition(|word| runs(word))?;
    let command_from = |span: &[&str]| -> Option<String> {
        let mut command: Vec<&str> = Vec::new();
        for word in span {
            if stops.contains(&bare(word)) {
                break;
            }
            let ends = word.ends_with(COMMAND_ENDS);
            command.push(word.trim_end_matches(COMMAND_ENDS));
            if ends {
                break;
            }
        }
        command
            .first()
            .is_some_and(|head| heads.iter().any(|known| known.as_str() == *head))
            .then(|| command.join(" "))
    };
    if let Some(after) = command_from(&words[verb + 1..]) {
        return Some(after);
    }
    let head = words[..verb]
        .iter()
        .rposition(|word| heads.iter().any(|known| known.as_str() == *word))?;
    command_from(&words[head..verb])
}

/// The paths `text` names, each once, in order.
pub(super) fn paths_in(text: &str) -> Vec<String> {
    let mut paths: Vec<String> = Vec::new();
    for token in super::write_request::tokens(text) {
        let path = super::write_request::clean_path_token(token.text);
        if super::write_request::looks_like_file_path(path)
            && super::write_request::safe_relative_path(path)
            && !paths.iter().any(|seen| seen == path)
        {
            paths.push(path.to_owned());
        }
    }
    paths
}

/// Whether a clause states the seeded return action.
fn returns_in(part: &str) -> bool {
    let lexicon = seed::lexicon();
    part.split_whitespace()
        .any(|word| lexicon.mentions_role("coding_return_action", &bare(word)))
}

/// The module-function request `task` states, or `None`.
///
/// The request names a seeded code construct (`coding_request_object`) to
/// write or add, a signature, the module it goes in, and -- when it names a
/// test (`coding_test_artifact_kind`) -- the one other path, the test module.
/// Mirrors `moduleFunctionRequest`.
#[must_use]
pub fn module_function_request(task: &str) -> Option<ModuleFunctionRequest> {
    let lexicon = seed::lexicon();
    let outside = outside_quotes(task);
    let normalized = crate::engine::normalize_prompt(&outside).to_lowercase();
    if !lexicon.mentions_role("coding_request_object", &normalized)
        || !(lexicon.mentions_role("coding_request_verb", &normalized)
            || lexicon.mentions_role("coding_member_add_action", &normalized))
    {
        return None;
    }
    let stated = signature(&outside)?;
    let parts = clauses(&outside);
    let at = parts
        .iter()
        .position(|part| signature(part).is_some_and(|found| found.name == stated.name));
    // The module is the path the signature's own clause names, before or
    // after it; otherwise the first path after the signature.
    let own = at.map_or_else(Vec::new, |index| paths_in(&parts[index]));
    let paths: Vec<String> = if own.len() == 1 {
        std::iter::once(own[0].clone())
            .chain(
                paths_in(&outside)
                    .into_iter()
                    .filter(|path| path != &own[0]),
            )
            .collect()
    } else {
        paths_in(&outside[stated.at..])
    };
    let module = paths.first()?.clone();
    let language = extension_language(&module)?;
    contract(&language)?;
    crate::coding::program_language_by_slug(&language)?;
    let others = &paths[1..];
    let wants_test = lexicon.mentions_role("coding_test_artifact_kind", &normalized);
    if others.len() > 1 || (wants_test && others.len() != 1) || (!wants_test && !others.is_empty())
    {
        return None;
    }
    // The specification is the signature's clause, joined by the relative
    // clause right after it when the return is stated there.
    let clause = match at {
        None => outside.clone(),
        Some(index)
            if !returns_in(&parts[index])
                && parts.get(index + 1).is_some_and(|next| returns_in(next)) =>
        {
            format!("{} {}", parts[index], parts[index + 1])
        }
        Some(index) => parts[index].clone(),
    };
    Some(ModuleFunctionRequest {
        name: stated.name,
        parameters: stated.parameters,
        at: stated.at,
        module,
        test: others.first().cloned(),
        language,
        clause,
        command: stated_command(&outside),
    })
}

/// One seeded binary operation: its fragment id, its `{left} <operator>
/// {right}` idiom, and the relations it `supports`.
struct RelationOperation {
    id: String,
    idiom: String,
    supports: Vec<String>,
}

/// Whether `idiom` is `{left} <operator> {right}`.
fn is_binary_idiom(idiom: &str) -> bool {
    idiom
        .strip_prefix("{left} ")
        .and_then(|rest| rest.strip_suffix(" {right}"))
        .is_some_and(|operator| !operator.is_empty() && !operator.contains(char::is_whitespace))
}

/// The binary operations the seed relates to a named arithmetic relation:
/// each `coding_fragment` of data/seed/coding-composition-fragments.lino whose
/// idiom is `{left} <operator> {right}`, with the reductions it `supports`.
/// Mirrors `relationOperations`.
fn relation_operations() -> Vec<RelationOperation> {
    let Some(text) =
        crate::coding::fragment_catalog::bootstrap_seed_text("coding-composition-fragments.lino")
    else {
        return Vec::new();
    };
    let root = parse_lino(&text);
    let Some(record) = root.children.first() else {
        return Vec::new();
    };
    record
        .children
        .iter()
        .map(|node| RelationOperation {
            // A record's line is its fragment id (`integer_add`), as the
            // fragment catalog reads the same file; a `meaning <id>` record
            // carries it as the id.
            id: if node.name == "meaning" {
                node.id.clone()
            } else {
                node.name.clone()
            },
            idiom: node.find_child_value("idiom").to_owned(),
            supports: node
                .children
                .iter()
                .filter(|child| child.name == "supports")
                .map(|child| child.id.clone())
                .collect(),
        })
        .filter(|operation| is_binary_idiom(&operation.idiom))
        .collect()
}

/// `left <operator> right` for the one arithmetic relation `text` names in
/// any seeded language, or `None` when it names none or several. Mirrors
/// `relationExpression`.
fn relation_expression(text: &str, samples: &[String]) -> Option<String> {
    let [left, right] = samples else {
        return None;
    };
    let lexicon = seed::lexicon();
    let normalized = crate::engine::normalize_prompt(text).to_lowercase();
    let named: Vec<RelationOperation> = relation_operations()
        .into_iter()
        .filter(|operation| {
            operation.supports.iter().any(|relation| {
                lexicon
                    .meaning(relation)
                    .is_some_and(|meaning| meaning.evidenced_in(&normalized))
            })
        })
        .collect();
    match named.as_slice() {
        [operation] => Some(fill(
            &operation.idiom,
            &[("left", left.as_str()), ("right", right.as_str())],
        )),
        _ => None,
    }
}

/// The calculator's value of `expression`. Mirrors `evaluated`.
fn evaluated(expression: &str) -> Option<String> {
    crate::calculation::evaluate_calculation(expression)
        .ok()
        .map(|evaluation| evaluation.formatted)
}

/// The specification's value at `samples`, computed by the calculator: the
/// clause after the seeded return action with the parameters bound to the
/// samples, or, when that names no operands, the arithmetic relation the
/// clause names around its return action applied to the samples in parameter
/// order. Mirrors `specifiedValue`.
fn specified_value(request: &ModuleFunctionRequest, samples: &[String]) -> Option<String> {
    let lexicon = seed::lexicon();
    let words: Vec<&str> = request.clause.split_whitespace().collect();
    let returns = words
        .iter()
        .position(|word| lexicon.mentions_role("coding_return_action", &bare(word)))?;
    let after_signature = request
        .clause
        .find(')')
        .map_or(request.clause.as_str(), |close| {
            &request.clause[close + 1..]
        });
    stated_value(
        &words[returns + 1..],
        after_signature,
        &request.parameters,
        samples,
    )
}

/// The value a stated return computes at `samples`.
///
/// The longest expression the words open with, its parameters bound to the
/// samples (`a - b to m.mjs` reads `2 - 3`; the words after it belong to the
/// request, PR #1188 T92), or else the arithmetic relation `relation_text`
/// names applied to the samples. Mirrors `statedValue`.
pub(super) fn stated_value(
    words: &[&str],
    relation_text: &str,
    parameters: &[String],
    samples: &[String],
) -> Option<String> {
    let bound = words
        .iter()
        .map(|word| {
            parameters
                .iter()
                .position(|parameter| *parameter == bare(word))
                .and_then(|index| samples.get(index))
                .map_or_else(|| (*word).to_owned(), Clone::clone)
        })
        .collect::<Vec<_>>();
    for end in (1..=bound.len()).rev() {
        if let Some(candidate) =
            crate::calculation::calculation_expression_candidates(&bound[..end].join(" "))
                .into_iter()
                .next()
        {
            return evaluated(&candidate.expression);
        }
    }
    evaluated(&relation_expression(relation_text, samples)?)
}

/// The function's source in `request.language`: the one seeded binary
/// operation whose idiom meets the specification at every sample pair of the
/// contract, applied to the parameters in order and lowered through the
/// language's IR lowering. The native counterpart of the shared solver's
/// synthesis in `moduleFunctionRecipe`.
fn synthesized_source(request: &ModuleFunctionRequest, samples: &[String]) -> Option<String> {
    let arity = request.parameters.len();
    if arity != 2 || samples.len() < arity {
        return None;
    }
    let pairs: Vec<&[String]> = samples.chunks_exact(arity).collect();
    let specified: Vec<String> = pairs
        .iter()
        .map(|pair| specified_value(request, pair))
        .collect::<Option<Vec<_>>>()?;
    let parameter = |name: &String| IrNode::Parameter {
        name: name.clone(),
        ty: IrType::Integer,
    };
    let program = |operation: &RelationOperation| ProgramIr {
        name: request.name.clone(),
        parameters: request
            .parameters
            .iter()
            .map(|name| (name.clone(), IrType::Integer))
            .collect(),
        result: IrType::Integer,
        body: IrNode::Apply {
            fragment: operation.id.clone(),
            arguments: request.parameters.iter().map(parameter).collect(),
        },
        fragments: vec![operation.id.clone()],
        source_urls: Vec::new(),
        source_licenses: Vec::new(),
        reuse: ReuseMode::Verbatim,
    };
    let catalog = FragmentCatalog::bootstrap();
    // The integer samples type the operands: an idiom shared by an integer
    // and a float operation (`{left} * {right}`) is the one whose typed
    // signature takes the integer parameters.
    let meeting: Vec<ProgramIr> = relation_operations()
        .iter()
        .filter(|operation| {
            pairs.iter().zip(&specified).all(|(pair, expected)| {
                evaluated(&fill(
                    &operation.idiom,
                    &[("left", pair[0].as_str()), ("right", pair[1].as_str())],
                ))
                .as_ref()
                    == Some(expected)
            })
        })
        .map(program)
        .filter(|ir| ir.type_check(&catalog).is_ok())
        .collect();
    let [ir] = meeting.as_slice() else {
        return None;
    };
    crate::coding::ir_lowering::lowering_for(&request.language)?
        .lower(ir, &catalog)
        .ok()
}

/// `source` with `name` imported from `specifier` through the contract's
/// import line. Mirrors `withImport`.
fn with_import(source: &str, template: &str, name: &str, specifier: &str) -> String {
    let filled = fill(template, &[("specifier", specifier)]);
    let (prefix, suffix) = filled
        .split_once(NAMES_SLOT)
        .unwrap_or((filled.as_str(), ""));
    let mut lines: Vec<String> = source.split('\n').map(str::to_owned).collect();
    if let Some(at) = lines
        .iter()
        .position(|line| line.starts_with(prefix) && line.ends_with(suffix))
    {
        let line = &lines[at];
        let mut names: Vec<String> = line[prefix.len()..line.len() - suffix.len()]
            .split(',')
            .map(|part| part.trim().to_owned())
            .collect();
        if !names.iter().any(|existing| existing == name) {
            names.push(name.to_owned());
            lines[at] = format!("{prefix}{}{suffix}", names.join(", "));
        }
        return lines.join("\n");
    }
    let head = prefix.split_whitespace().next().unwrap_or(prefix);
    let last = lines.iter().rposition(|line| line.starts_with(head));
    let insert_at = last.map_or(0, |index| index + 1);
    lines.insert(insert_at, format!("{prefix}{name}{suffix}"));
    lines.join("\n")
}

/// The import specifier of `module` from a file at `from`, both
/// workspace-relative. Mirrors `specifierFrom`.
fn specifier_from(from: &str, module: &str) -> String {
    let from_parts: Vec<&str> = from.split('/').collect();
    let base = &from_parts[..from_parts.len() - 1];
    let target: Vec<&str> = module.split('/').collect();
    let mut shared = 0;
    while shared < base.len() && shared + 1 < target.len() && base[shared] == target[shared] {
        shared += 1;
    }
    let up: Vec<&str> = base[shared..].iter().map(|_| "..").collect();
    let path = up
        .iter()
        .copied()
        .chain(target[shared..].iter().copied())
        .collect::<Vec<_>>()
        .join("/");
    if up.is_empty() {
        format!("./{path}")
    } else {
        path
    }
}

/// `text` ending in a newline unless it is empty. Mirrors `withFinalNewline`.
fn with_final_newline(text: &str) -> String {
    if text.is_empty() || text.ends_with('\n') {
        text.to_owned()
    } else {
        format!("{text}\n")
    }
}

/// The recipe that adds the function and its test and runs the check.
/// Mirrors `moduleFunctionRecipe`.
fn module_function_recipe(
    request: &ModuleFunctionRequest,
    module_source: &str,
    test_source: &str,
) -> Option<ExecutionRecipe> {
    let terms = contract(&request.language)?;
    let catalog = crate::coding::program_language_by_slug(&request.language)?;
    let samples: Vec<String> = terms
        .find_child_value("samples")
        .split_whitespace()
        .map(str::to_owned)
        .collect();
    let program = synthesized_source(request, &samples)?;
    let definition = fill(
        terms.find_child_value("definition"),
        &[("name", request.name.as_str())],
    );
    let defined = module_source
        .split('\n')
        .any(|line| line.starts_with(&definition));
    let source = if defined {
        module_source.to_owned()
    } else {
        let separator = if module_source.trim().is_empty() {
            ""
        } else {
            "\n"
        };
        format!("{}{separator}{program}", with_final_newline(module_source))
    };
    let mut commands: Vec<String> = catalog
        .execution
        .check_command
        .as_deref()
        .into_iter()
        .map(|command| command.replace(catalog.save_as.as_ref(), &request.module))
        .collect();
    let mut supporting_files = Vec::new();
    if let Some(test) = &request.test {
        let used: Vec<String> = samples
            .iter()
            .take(request.parameters.len())
            .cloned()
            .collect();
        if used.len() != request.parameters.len() {
            return None;
        }
        let expected = specified_value(request, &used)?;
        let specifier = specifier_from(test, &request.module);
        let base = if test_source.trim().is_empty() {
            terms.find_child_value("header").to_owned()
        } else {
            with_final_newline(test_source)
        };
        let imported = with_import(
            &base,
            terms.find_child_value("import"),
            &request.name,
            &specifier,
        );
        let test_case = fill(
            terms.find_child_value("case"),
            &[
                ("name", request.name.as_str()),
                ("arguments", used.join(", ").as_str()),
                ("expected", expected.as_str()),
            ],
        );
        let source = if imported.contains(&test_case) {
            imported
        } else {
            format!("{imported}{test_case}")
        };
        supporting_files.push(ExecutionRecipeFile {
            path: test.clone(),
            source,
        });
    }
    let run = request.command.clone().or_else(|| {
        request
            .test
            .as_ref()
            .map(|test| fill(terms.find_child_value("run"), &[("test", test.as_str())]))
    });
    commands.extend(run);
    Some(ExecutionRecipe {
        language: request.language.clone(),
        source,
        path: request.module.clone(),
        supporting_files,
        commands,
    })
}

/// The file `path` as the transcript's read returned it; empty for a missing
/// file, `None` when unread. Mirrors `readSource`.
pub(super) fn read_source(current_turn: &[ChatMessage], path: &str) -> Option<String> {
    let read =
        super::workspace_change::result_for_path(current_turn, Capability::Read, path, None)?;
    let missing = super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some();
    Some(if missing {
        String::new()
    } else {
        super::code_artifact::source_from_read_result(&read)
    })
}

/// Plan the next step of a module-function request: read the module and the
/// test module, then hand the computed recipe to the execution-recipe
/// reroute. Mirrors `planModuleFunctionStep`.
pub(super) fn plan_module_function_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    if let Some(request) = discovery::observed_callable_request(task) {
        return discovery::plan_observed_callable_step(request, messages, tool_names, result);
    }
    let request = module_function_request(task)?;
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    let read_tool = super::capability_router::tool_for(tool_names, Capability::Read);
    let mut sources = Vec::new();
    for path in std::iter::once(&request.module).chain(request.test.iter()) {
        let Some(source) = read_source(current_turn, path) else {
            return read_tool.map(|tool| {
                super::planner::plan_one(tool, super::workspace_change::read_arguments(path))
            });
        };
        sources.push(source);
    }
    let module_source = sources.first().map_or("", String::as_str);
    let test_source = sources.get(1).map_or("", String::as_str);
    let recipe = module_function_recipe(&request, module_source, test_source)?;
    super::command_reroute::plan_symbolic_command_reroute(
        messages,
        tool_names,
        &SymbolicAnswer {
            intent: "module_function".to_owned(),
            answer: String::new(),
            confidence: 1.0,
            evidence_links: Vec::new(),
            thinking_steps: Vec::new(),
            links_notation: String::new(),
            execution_recipe: Some(Box::new(recipe)),
        },
    )
}

changes.expected:
//! Add a synthesized function to an existing source module, a test of it to
//! its test module, and run the stated command (PR #1188 dogfooding, T1):
//!
//! ```text
//! Add a function multiply(a, b) to math.mjs that returns a times b, add a
//! test for it to math.test.mjs, and run node --test to confirm it passes.
//! ```
//!
//! The native twin of `js/agentic/module_function.mjs`, function by function.
//! Nothing here knows the task. The module's language is the one the seeded
//! extension table of `data/seed/page-formalization-rules.lino` names; the
//! test's expected value is computed from the specification itself -- the
//! clause after the seeded return action, its parameters bound to the
//! contract's sample arguments, or the seeded arithmetic relation it names --
//! evaluated by the calculator, never from the synthesized code. The edits and
//! the command run through the execution-recipe reroute, so the module and the
//! test are written whole after they were read, and the request's own command
//! is the verification.
//!
//! One step differs from the browser root: the JavaScript arm synthesizes the
//! function with the shared solver's browser composer, which the native
//! solver does not have. The native arm searches the seeded binary operations
//! instead (`synthesized_source`): the one whose idiom meets the
//! specification at every sample pair of the contract is lowered through the
//! language's IR lowering (`coding/ir_lowering`).

mod discovery;

use super::final_result::FinalResult;
use super::planner::{AgenticPlan, Capability};
use crate::coding::fragment_catalog::FragmentCatalog;
use crate::coding::program_ir::{IrNode, IrType, ProgramIr, ReuseMode};
use crate::engine::{ExecutionRecipe, ExecutionRecipeFile, SymbolicAnswer};
use crate::protocol::ChatMessage;
use crate::seed::{self, parser::LinoNode, parser::parse_lino};

const CONTRACTS: &str = include_str!("../../embedded/data/meta/function-test-contracts.lino");
const EXTENSIONS: &str = include_str!("../../embedded/data/seed/page-formalization-rules.lino");

/// The marks that end a command's last word: sentence and clause marks in
/// any script. Mirrors `COMMAND_ENDS` in `js/agentic/module_function.mjs`.
const COMMAND_ENDS: [char; 11] = [
    ',', ';', '.', '!', '?', '\u{ff0c}', '\u{ff1b}', '\u{3002}', '\u{ff01}', '\u{ff1f}', '\u{0964}',
];

/// The ideographic and Devanagari marks that end a clause wherever they sit.
const SCRIPT_CLAUSE_MARKS: [char; 6] = [
    '\u{ff0c}', '\u{ff1b}', '\u{3002}', '\u{ff01}', '\u{ff1f}', '\u{0964}',
];

/// A module-function request: the signature, the module it goes in, the test
/// module (when the request names a test), the module's language, the
/// specification clause and the stated command.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModuleFunctionRequest {
    pub name: String,
    pub parameters: Vec<String>,
    pub at: usize,
    pub module: String,
    pub test: Option<String>,
    pub language: String,
    pub clause: String,
    pub command: Option<String>,
}

/// `name(a, b)` and the byte offset it starts at.
pub(super) struct Signature {
    pub(super) name: String,
    pub(super) parameters: Vec<String>,
    pub(super) at: usize,
}

/// The import-line slot the imported names fill.
const NAMES_SLOT: &str = concat!("{", "names", "}");

/// `template` with each `{slot}` replaced. Mirrors `fill`.
fn fill(template: &str, slots: &[(&str, &str)]) -> String {
    slots
        .iter()
        .fold(template.to_owned(), |text, (slot, value)| {
            text.replace(&format!("{{{slot}}}"), value)
        })
}

/// A word without its edge punctuation, lowercased. Mirrors `bare`.
fn bare(word: &str) -> String {
    word.trim_matches(|character: char| !character.is_alphanumeric())
        .to_lowercase()
}

/// The function-test contract of `language`. Mirrors `contract`.
pub(super) fn contract(language: &str) -> Option<LinoNode> {
    let root = parse_lino(CONTRACTS);
    root.children
        .first()?
        .children
        .iter()
        .find(|node| node.name == "language" && node.id == language)
        .cloned()
}

/// The language the seeded extension table names for `path`. Mirrors
/// `extensionLanguage`.
pub(super) fn extension_language(path: &str) -> Option<String> {
    let root = parse_lino(EXTENSIONS);
    root.children
        .first()?
        .children
        .iter()
        .filter(|node| node.name == "extension")
        .find(|node| {
            let suffix = node.find_child_value("suffix");
            !suffix.is_empty() && path.ends_with(suffix)
        })
        .map(|node| node.find_child_value("language").to_owned())
}

/// The request without its quoted segments. Mirrors `outsideQuotes`.
fn outside_quotes(request: &str) -> String {
    let mut outside = String::new();
    let mut cursor = 0;
    for segment in crate::normal_markov::quoted_segment_spans(request) {
        if segment.start < cursor {
            continue;
        }
        outside.push_str(&request[cursor..segment.start]);
        outside.push(' ');
        cursor = segment.end;
    }
    outside.push_str(&request[cursor..]);
    outside
}

/// The request's clauses: split at `,` `;` and sentence ends (in any script)
/// outside parentheses. Mirrors `clauses`.
fn clauses(request: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth: usize = 0;
    let mut start = 0;
    let characters: Vec<(usize, char)> = request.char_indices().collect();
    for (position, (index, character)) in characters.iter().copied().enumerate() {
        if character == '(' {
            depth += 1;
        } else if character == ')' {
            depth = depth.saturating_sub(1);
        } else if depth == 0
            && (SCRIPT_CLAUSE_MARKS.contains(&character)
                || (matches!(character, ',' | ';' | '.' | '!' | '?')
                    && characters
                        .get(position + 1)
                        .is_none_or(|(_, next)| next.is_whitespace())))
        {
            out.push(request[start..index].to_owned());
            start = index + character.len_utf8();
        }
    }
    out.push(request[start..].to_owned());
    out.into_iter()
        .map(|clause| clause.trim().to_owned())
        .filter(|clause| !clause.is_empty())
        .collect()
}

/// Whether `text` is an identifier of the signature grammar (`[A-Za-z_$][\w$]*`).
fn is_identifier(text: &str) -> bool {
    let mut characters = text.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_' || first == '$')
        && characters.all(|character| {
            character.is_ascii_alphanumeric() || character == '_' || character == '$'
        })
}

/// `name(a, b)`: the first call-shaped signature whose parameters are
/// identifiers. Mirrors `signature`.
pub(super) fn signature(text: &str) -> Option<Signature> {
    for (open, _) in text.match_indices('(') {
        let Some(close) = text[open + 1..]
            .find([')', '('])
            .map(|offset| open + 1 + offset)
        else {
            continue;
        };
        if !text[close..].starts_with(')') {
            continue;
        }
        let head = text[..open].trim_end();
        let name_start = head
            .char_indices()
            .rev()
            .take_while(|(_, character)| {
                character.is_ascii_alphanumeric() || *character == '_' || *character == '$'
            })
            .last()
            .map(|(index, _)| index);
        // The name starts at its first letter, `_` or `$`, as the regular
        // expression's leftmost match does ("2both(" names `both`).
        let Some(name_start) = name_start.and_then(|start| {
            head[start..]
                .char_indices()
                .find(|(_, character)| {
                    character.is_ascii_alphabetic() || *character == '_' || *character == '$'
                })
                .map(|(offset, _)| start + offset)
        }) else {
            continue;
        };
        let name = &head[name_start..];
        if !is_identifier(name) {
            continue;
        }
        let parameters: Vec<String> = text[open + 1..close]
            .split(',')
            .map(|part| part.trim().to_owned())
            .collect();
        if parameters.iter().all(|parameter| is_identifier(parameter)) {
            return Some(Signature {
                name: name.to_owned(),
                parameters,
                at: name_start,
            });
        }
    }
    None
}

/// The command the request's last seeded run verb names, headed by a seeded
/// shell token: the words after the verb, or, in a verb-final clause, the
/// words from the shell token up to the verb. Mirrors `statedCommand`.
fn stated_command(request: &str) -> Option<String> {
    let vocabulary = seed::terminal_command_vocabulary();
    let heads: Vec<&String> = vocabulary
        .shell_tokens
        .iter()
        .chain(vocabulary.bare_shell_tokens.iter())
        .collect();
    let lexicon = seed::lexicon();
    let mut stops = lexicon.words_for_role(seed::ROLE_STATEMENT_FUNCTION_WORD);
    stops.extend(lexicon.words_for_role(seed::ROLE_SKILL_PROCEDURE_CLAUSE_SEPARATOR));
    let words: Vec<&str> = request.split_whitespace().collect();
    let runs = |word: &str| {
        let plain = bare(word);
        vocabulary
            .run_verbs
            .contains(&super::shell_command_policy::normalize_command_word(word))
            || vocabulary.run_verbs.contains(&plain)
            || vocabulary
                .cjk_run_verbs
                .iter()
                .any(|verb| plain.ends_with(verb.as_str()))
    };
    let verb = words.iter().rposition(|word| runs(word))?;
    let command_from = |span: &[&str]| -> Option<String> {
        let mut command: Vec<&str> = Vec::new();
        for word in span {
            if stops.contains(&bare(word)) {
                break;
            }
            let ends = word.ends_with(COMMAND_ENDS);
            command.push(word.trim_end_matches(COMMAND_ENDS));
            if ends {
                break;
            }
        }
        command
            .first()
            .is_some_and(|head| heads.iter().any(|known| known.as_str() == *head))
            .then(|| command.join(" "))
    };
    if let Some(after) = command_from(&words[verb + 1..]) {
        return Some(after);
    }
    for (index, word) in words[verb + 1..].iter().enumerate() {
        if heads.iter().any(|known| known.as_str() == *word) {
            return command_from(&words[verb + 1 + index..]);
        }
        if word.ends_with(['.', '!', '?', '\u{ff01}', '\u{ff1f}', '\u{3002}', '\u{0964}']) {
            break;
        }
    }
    let head = words[..verb]
        .iter()
        .rposition(|word| heads.iter().any(|known| known.as_str() == *word))?;
    command_from(&words[head..verb])
}

/// The paths `text` names, each once, in order.
pub(super) fn paths_in(text: &str) -> Vec<String> {
    let mut paths: Vec<String> = Vec::new();
    for token in super::write_request::tokens(text) {
        let path = super::write_request::clean_path_token(token.text);
        if super::write_request::looks_like_file_path(path)
            && super::write_request::safe_relative_path(path)
            && !paths.iter().any(|seen| seen == path)
        {
            paths.push(path.to_owned());
        }
    }
    paths
}

/// Whether a clause states the seeded return action.
fn returns_in(part: &str) -> bool {
    let lexicon = seed::lexicon();
    part.split_whitespace()
        .any(|word| lexicon.mentions_role("coding_return_action", &bare(word)))
}

/// The module-function request `task` states, or `None`.
///
/// The request names a seeded code construct (`coding_request_object`) to
/// write or add, a signature, the module it goes in, and -- when it names a
/// test (`coding_test_artifact_kind`) -- the one other path, the test module.
/// Mirrors `moduleFunctionRequest`.
#[must_use]
pub fn module_function_request(task: &str) -> Option<ModuleFunctionRequest> {
    let lexicon = seed::lexicon();
    let outside = outside_quotes(task);
    let normalized = crate::engine::normalize_prompt(&outside).to_lowercase();
    if !lexicon.mentions_role("coding_request_object", &normalized)
        || !(lexicon.mentions_role("coding_request_verb", &normalized)
            || lexicon.mentions_role("coding_member_add_action", &normalized))
    {
        return None;
    }
    let stated = signature(&outside)?;
    let parts = clauses(&outside);
    let at = parts
        .iter()
        .position(|part| signature(part).is_some_and(|found| found.name == stated.name));
    // The module is the path the signature's own clause names, before or
    // after it; otherwise the first path after the signature.
    let own = at.map_or_else(Vec::new, |index| paths_in(&parts[index]));
    let paths: Vec<String> = if own.len() == 1 {
        std::iter::once(own[0].clone())
            .chain(
                paths_in(&outside)
                    .into_iter()
                    .filter(|path| path != &own[0]),
            )
            .collect()
    } else {
        paths_in(&outside[stated.at..])
    };
    let module = paths.first()?.clone();
    let language = extension_language(&module)?;
    contract(&language)?;
    crate::coding::program_language_by_slug(&language)?;
    let others = &paths[1..];
    let wants_test = lexicon.mentions_role("coding_test_artifact_kind", &normalized);
    if others.len() > 1 || (wants_test && others.len() != 1) || (!wants_test && !others.is_empty())
    {
        return None;
    }
    // The specification is the signature's clause, joined by the relative
    // clause right after it when the return is stated there.
    let clause = match at {
        None => outside.clone(),
        Some(index)
            if !returns_in(&parts[index])
                && parts.get(index + 1).is_some_and(|next| returns_in(next)) =>
        {
            format!("{} {}", parts[index], parts[index + 1])
        }
        Some(index) => parts[index].clone(),
    };
    Some(ModuleFunctionRequest {
        name: stated.name,
        parameters: stated.parameters,
        at: stated.at,
        module,
        test: others.first().cloned(),
        language,
        clause,
        command: stated_command(&outside),
    })
}

/// One seeded binary operation: its fragment id, its `{left} <operator>
/// {right}` idiom, and the relations it `supports`.
struct RelationOperation {
    id: String,
    idiom: String,
    supports: Vec<String>,
}

/// Whether `idiom` is `{left} <operator> {right}`.
fn is_binary_idiom(idiom: &str) -> bool {
    idiom
        .strip_prefix("{left} ")
        .and_then(|rest| rest.strip_suffix(" {right}"))
        .is_some_and(|operator| !operator.is_empty() && !operator.contains(char::is_whitespace))
}

/// The binary operations the seed relates to a named arithmetic relation:
/// each `coding_fragment` of data/seed/coding-composition-fragments.lino whose
/// idiom is `{left} <operator> {right}`, with the reductions it `supports`.
/// Mirrors `relationOperations`.
fn relation_operations() -> Vec<RelationOperation> {
    let Some(text) =
        crate::coding::fragment_catalog::bootstrap_seed_text("coding-composition-fragments.lino")
    else {
        return Vec::new();
    };
    let root = parse_lino(&text);
    let Some(record) = root.children.first() else {
        return Vec::new();
    };
    record
        .children
        .iter()
        .map(|node| RelationOperation {
            // A record's line is its fragment id (`integer_add`), as the
            // fragment catalog reads the same file; a `meaning <id>` record
            // carries it as the id.
            id: if node.name == "meaning" {
                node.id.clone()
            } else {
                node.name.clone()
            },
            idiom: node.find_child_value("idiom").to_owned(),
            supports: node
                .children
                .iter()
                .filter(|child| child.name == "supports")
                .map(|child| child.id.clone())
                .collect(),
        })
        .filter(|operation| is_binary_idiom(&operation.idiom))
        .collect()
}

/// `left <operator> right` for the one arithmetic relation `text` names in
/// any seeded language, or `None` when it names none or several. Mirrors
/// `relationExpression`.
fn relation_expression(text: &str, samples: &[String]) -> Option<String> {
    let [left, right] = samples else {
        return None;
    };
    let lexicon = seed::lexicon();
    let normalized = crate::engine::normalize_prompt(text).to_lowercase();
    let named: Vec<RelationOperation> = relation_operations()
        .into_iter()
        .filter(|operation| {
            operation.supports.iter().any(|relation| {
                lexicon
                    .meaning(relation)
                    .is_some_and(|meaning| meaning.evidenced_in(&normalized))
            })
        })
        .collect();
    match named.as_slice() {
        [operation] => Some(fill(
            &operation.idiom,
            &[("left", left.as_str()), ("right", right.as_str())],
        )),
        _ => None,
    }
}

/// The calculator's value of `expression`. Mirrors `evaluated`.
fn evaluated(expression: &str) -> Option<String> {
    crate::calculation::evaluate_calculation(expression)
        .ok()
        .map(|evaluation| evaluation.formatted)
}

/// The specification's value at `samples`, computed by the calculator: the
/// clause after the seeded return action with the parameters bound to the
/// samples, or, when that names no operands, the arithmetic relation the
/// clause names around its return action applied to the samples in parameter
/// order. Mirrors `specifiedValue`.
fn specified_value(request: &ModuleFunctionRequest, samples: &[String]) -> Option<String> {
    let lexicon = seed::lexicon();
    let words: Vec<&str> = request.clause.split_whitespace().collect();
    let returns = words
        .iter()
        .position(|word| lexicon.mentions_role("coding_return_action", &bare(word)))?;
    let after_signature = request
        .clause
        .find(')')
        .map_or(request.clause.as_str(), |close| {
            &request.clause[close + 1..]
        });
    stated_value(
        &words[returns + 1..],
        after_signature,
        &request.parameters,
        samples,
    )
}

/// The value a stated return computes at `samples`.
///
/// The longest expression the words open with, its parameters bound to the
/// samples (`a - b to m.mjs` reads `2 - 3`; the words after it belong to the
/// request, PR #1188 T92), or else the arithmetic relation `relation_text`
/// names applied to the samples. Mirrors `statedValue`.
pub(super) fn stated_value(
    words: &[&str],
    relation_text: &str,
    parameters: &[String],
    samples: &[String],
) -> Option<String> {
    let bound = words
        .iter()
        .map(|word| {
            parameters
                .iter()
                .position(|parameter| *parameter == bare(word))
                .and_then(|index| samples.get(index))
                .map_or_else(|| (*word).to_owned(), Clone::clone)
        })
        .collect::<Vec<_>>();
    for end in (1..=bound.len()).rev() {
        if let Some(candidate) =
            crate::calculation::calculation_expression_candidates(&bound[..end].join(" "))
                .into_iter()
                .next()
        {
            return evaluated(&candidate.expression);
        }
    }
    evaluated(&relation_expression(relation_text, samples)?)
}

/// The function's source in `request.language`: the one seeded binary
/// operation whose idiom meets the specification at every sample pair of the
/// contract, applied to the parameters in order and lowered through the
/// language's IR lowering. The native counterpart of the shared solver's
/// synthesis in `moduleFunctionRecipe`.
fn synthesized_source(request: &ModuleFunctionRequest, samples: &[String]) -> Option<String> {
    let arity = request.parameters.len();
    if arity != 2 || samples.len() < arity {
        return None;
    }
    let pairs: Vec<&[String]> = samples.chunks_exact(arity).collect();
    let specified: Vec<String> = pairs
        .iter()
        .map(|pair| specified_value(request, pair))
        .collect::<Option<Vec<_>>>()?;
    let parameter = |name: &String| IrNode::Parameter {
        name: name.clone(),
        ty: IrType::Integer,
    };
    let program = |operation: &RelationOperation| ProgramIr {
        name: request.name.clone(),
        parameters: request
            .parameters
            .iter()
            .map(|name| (name.clone(), IrType::Integer))
            .collect(),
        result: IrType::Integer,
        body: IrNode::Apply {
            fragment: operation.id.clone(),
            arguments: request.parameters.iter().map(parameter).collect(),
        },
        fragments: vec![operation.id.clone()],
        source_urls: Vec::new(),
        source_licenses: Vec::new(),
        reuse: ReuseMode::Verbatim,
    };
    let catalog = FragmentCatalog::bootstrap();
    // The integer samples type the operands: an idiom shared by an integer
    // and a float operation (`{left} * {right}`) is the one whose typed
    // signature takes the integer parameters.
    let meeting: Vec<ProgramIr> = relation_operations()
        .iter()
        .filter(|operation| {
            pairs.iter().zip(&specified).all(|(pair, expected)| {
                evaluated(&fill(
                    &operation.idiom,
                    &[("left", pair[0].as_str()), ("right", pair[1].as_str())],
                ))
                .as_ref()
                    == Some(expected)
            })
        })
        .map(program)
        .filter(|ir| ir.type_check(&catalog).is_ok())
        .collect();
    let [ir] = meeting.as_slice() else {
        return None;
    };
    crate::coding::ir_lowering::lowering_for(&request.language)?
        .lower(ir, &catalog)
        .ok()
}

/// `source` with `name` imported from `specifier` through the contract's
/// import line. Mirrors `withImport`.
fn with_import(source: &str, template: &str, name: &str, specifier: &str) -> String {
    let filled = fill(template, &[("specifier", specifier)]);
    let (prefix, suffix) = filled
        .split_once(NAMES_SLOT)
        .unwrap_or((filled.as_str(), ""));
    let mut lines: Vec<String> = source.split('\n').map(str::to_owned).collect();
    if let Some(at) = lines
        .iter()
        .position(|line| line.starts_with(prefix) && line.ends_with(suffix))
    {
        let line = &lines[at];
        let mut names: Vec<String> = line[prefix.len()..line.len() - suffix.len()]
            .split(',')
            .map(|part| part.trim().to_owned())
            .collect();
        if !names.iter().any(|existing| existing == name) {
            names.push(name.to_owned());
            lines[at] = format!("{prefix}{}{suffix}", names.join(", "));
        }
        return lines.join("\n");
    }
    let head = prefix.split_whitespace().next().unwrap_or(prefix);
    let last = lines.iter().rposition(|line| line.starts_with(head));
    let insert_at = last.map_or(0, |index| index + 1);
    lines.insert(insert_at, format!("{prefix}{name}{suffix}"));
    lines.join("\n")
}

/// The import specifier of `module` from a file at `from`, both
/// workspace-relative. Mirrors `specifierFrom`.
fn specifier_from(from: &str, module: &str) -> String {
    let from_parts: Vec<&str> = from.split('/').collect();
    let base = &from_parts[..from_parts.len() - 1];
    let target: Vec<&str> = module.split('/').collect();
    let mut shared = 0;
    while shared < base.len() && shared + 1 < target.len() && base[shared] == target[shared] {
        shared += 1;
    }
    let up: Vec<&str> = base[shared..].iter().map(|_| "..").collect();
    let path = up
        .iter()
        .copied()
        .chain(target[shared..].iter().copied())
        .collect::<Vec<_>>()
        .join("/");
    if up.is_empty() {
        format!("./{path}")
    } else {
        path
    }
}

/// `text` ending in a newline unless it is empty. Mirrors `withFinalNewline`.
fn with_final_newline(text: &str) -> String {
    if text.is_empty() || text.ends_with('\n') {
        text.to_owned()
    } else {
        format!("{text}\n")
    }
}

/// The recipe that adds the function and its test and runs the check.
/// Mirrors `moduleFunctionRecipe`.
fn module_function_recipe(
    request: &ModuleFunctionRequest,
    module_source: &str,
    test_source: &str,
) -> Option<ExecutionRecipe> {
    let terms = contract(&request.language)?;
    let catalog = crate::coding::program_language_by_slug(&request.language)?;
    let samples: Vec<String> = terms
        .find_child_value("samples")
        .split_whitespace()
        .map(str::to_owned)
        .collect();
    let program = synthesized_source(request, &samples)?;
    let definition = fill(
        terms.find_child_value("definition"),
        &[("name", request.name.as_str())],
    );
    let defined = module_source
        .split('\n')
        .any(|line| line.starts_with(&definition));
    let source = if defined {
        module_source.to_owned()
    } else {
        let separator = if module_source.trim().is_empty() {
            ""
        } else {
            "\n"
        };
        format!("{}{separator}{program}", with_final_newline(module_source))
    };
    let mut commands: Vec<String> = catalog
        .execution
        .check_command
        .as_deref()
        .into_iter()
        .map(|command| command.replace(catalog.save_as.as_ref(), &request.module))
        .collect();
    let mut supporting_files = Vec::new();
    if let Some(test) = &request.test {
        let used: Vec<String> = samples
            .iter()
            .take(request.parameters.len())
            .cloned()
            .collect();
        if used.len() != request.parameters.len() {
            return None;
        }
        let expected = specified_value(request, &used)?;
        let specifier = specifier_from(test, &request.module);
        let base = if test_source.trim().is_empty() {
            terms.find_child_value("header").to_owned()
        } else {
            with_final_newline(test_source)
        };
        let imported = with_import(
            &base,
            terms.find_child_value("import"),
            &request.name,
            &specifier,
        );
        let test_case = fill(
            terms.find_child_value("case"),
            &[
                ("name", request.name.as_str()),
                ("arguments", used.join(", ").as_str()),
                ("expected", expected.as_str()),
            ],
        );
        let source = if imported.contains(&test_case) {
            imported
        } else {
            format!("{imported}{test_case}")
        };
        supporting_files.push(ExecutionRecipeFile {
            path: test.clone(),
            source,
        });
    }
    let run = request.command.clone().or_else(|| {
        request
            .test
            .as_ref()
            .map(|test| fill(terms.find_child_value("run"), &[("test", test.as_str())]))
    });
    commands.extend(run);
    Some(ExecutionRecipe {
        language: request.language.clone(),
        source,
        path: request.module.clone(),
        supporting_files,
        commands,
    })
}

/// The file `path` as the transcript's read returned it; empty for a missing
/// file, `None` when unread. Mirrors `readSource`.
pub(super) fn read_source(current_turn: &[ChatMessage], path: &str) -> Option<String> {
    let read =
        super::workspace_change::result_for_path(current_turn, Capability::Read, path, None)?;
    let missing = super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some();
    Some(if missing {
        String::new()
    } else {
        super::code_artifact::source_from_read_result(&read)
    })
}

/// Plan the next step of a module-function request: read the module and the
/// test module, then hand the computed recipe to the execution-recipe
/// reroute. Mirrors `planModuleFunctionStep`.
pub(super) fn plan_module_function_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    if let Some(request) = discovery::observed_callable_request(task) {
        return discovery::plan_observed_callable_step(request, messages, tool_names, result);
    }
    let request = module_function_request(task)?;
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    let read_tool = super::capability_router::tool_for(tool_names, Capability::Read);
    let mut sources = Vec::new();
    for path in std::iter::once(&request.module).chain(request.test.iter()) {
        let Some(source) = read_source(current_turn, path) else {
            return read_tool.map(|tool| {
                super::planner::plan_one(tool, super::workspace_change::read_arguments(path))
            });
        };
        sources.push(source);
    }
    let module_source = sources.first().map_or("", String::as_str);
    let test_source = sources.get(1).map_or("", String::as_str);
    let recipe = module_function_recipe(&request, module_source, test_source)?;
    super::command_reroute::plan_symbolic_command_reroute(
        messages,
        tool_names,
        &SymbolicAnswer {
            intent: "module_function".to_owned(),
            answer: String::new(),
            confidence: 1.0,
            evidence_links: Vec::new(),
            thinking_steps: Vec::new(),
            links_notation: String::new(),
            execution_recipe: Some(Box::new(recipe)),
        },
    )
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import test from 'node:test';
import { drive } from '../../../experiments/js_dogfood/drive.mjs';
import { WorkerHost } from '../../../js/server/worker-host.mjs';
import { installNodeHost } from '../../../js/agentic/node-host.mjs';
import { planChatStep } from '../../../js/agentic/planner.mjs';
import { moduleFunctionRequest, observedCallableRequest, planModuleFunctionStep } from '../../../js/agentic/module_function.mjs';
import { FinalDisposition, canDeliverFinal } from '../../../js/agentic/final_result.mjs';
await installNodeHost(new WorkerHost());
const prompt = 'Add exported caption(pick) to nested/output.mjs. Read first.mjs and second.mjs before authoring. '
  + 'Run the supplied accept.test.mjs acceptance command, node --test accept.test.mjs, and report the real result.';
const sha = (content) => createHash('sha256').update(content).digest('hex');
const fixture = (body) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'callable-discovery-'));
  const entries = { 'nested/output.mjs': '// existing destination\n',
    'first.mjs': 'export function take(input) { return input.value; }\n',
    'second.mjs': 'export function print(value) { return String(value); }\n',
    'accept.test.mjs': 'throw new Error("acceptance must not run before a candidate exists");\n' };
  for (const [name, content] of Object.entries(entries)) {
    fs.mkdirSync(path.dirname(path.join(dir, name)), { recursive: true });
    fs.writeFileSync(path.join(dir, name), content);
  }
  return Promise.resolve(body(dir, entries)).finally(() => fs.rmSync(dir, { recursive: true, force: true }));
};
const receipt = (name, content) => [{ role: 'assistant', content: '', tool_calls: [
  { id: name, type: 'function', function: { name: 'read', arguments: JSON.stringify({ path: name }) } } ] },
{ role: 'tool', content, tool_call_id: name }];

test('destination, immutable inputs and acceptance are declaration-scoped', () => {
  assert.deepEqual(observedCallableRequest(prompt), { name: 'caption', parameters: ['pick'], destination: 'nested/output.mjs',
    inputs: ['first.mjs', 'second.mjs'], acceptance: ['accept.test.mjs'], command: 'node --test accept.test.mjs' });
});

test('adjacent declared module and alias signature bind the same reusable discovery', () => {
  const request = observedCallableRequest('Implement a JavaScript module reports/result.mjs. Export describeChosen(selection). '
    + 'Read left.mjs and right.mjs. Run node --test gate.mjs.');
  assert.equal(request.destination, 'reports/result.mjs');
  assert.equal(request.name, 'describeChosen');
  assert.deepEqual(request.inputs, ['left.mjs', 'right.mjs']);
});

test('ambiguous destinations and quoted call shapes are not guessed', () => {
  assert.equal(observedCallableRequest('Add caption(pick) to a.mjs and b.mjs. Read source.mjs.'), null);
  assert.equal(observedCallableRequest('Implement a module result.mjs. Read source.mjs with the label «caption(pick)». '), null);
  assert.equal(observedCallableRequest('Read existing.mjs then execute arbitrary(input). Read source.mjs.'), null);
});

test('existing arithmetic module/test request remains on its original route', () => {
  const arithmetic = 'Add a function multiply(a, b) to math.mjs that returns a times b, add a test for it to math.test.mjs, and run node --test.';
  assert.equal(observedCallableRequest(arithmetic), null);
  assert.equal(moduleFunctionRequest(arithmetic).module, 'math.mjs');
  assert.equal(moduleFunctionRequest(arithmetic).command, 'node --test');
});

test('actual planner reads all operands, reports exact missing contracts, and changes no bytes', async () => {
  await fixture(async (dir, entries) => {
    const result = await drive(planChatStep, dir, prompt + ' Incidental issue numbers are 188 and 558.', { steps: 12 });
    assert.deepEqual(result.transcript.map((call) => [call.tool, JSON.parse(call.arguments).path]),
      Object.keys(entries).map((name) => ['read', name]));
    const evidence = JSON.parse(result.answer.slice(result.answer.indexOf('\n') + 1));
    assert.equal(evidence.reason, 'MissingContract');
    assert.equal(evidence.authored, false);
    assert.equal(evidence.verified, false);
    assert.deepEqual(evidence.missingContracts.map((item) => item.path), ['first.mjs', 'second.mjs']);
    for (const observation of evidence.observations) {
      assert.equal(observation.contentId, sha(entries[observation.path]));
      assert.equal(fs.readFileSync(path.join(dir, observation.path), 'utf8'), entries[observation.path]);
    }
  });
});

test('an absent destination is observed without creating it', async () => {
  await fixture(async (dir) => {
    fs.unlinkSync(path.join(dir, 'nested/output.mjs'));
    const result = await drive(planChatStep, dir, prompt, { steps: 12 });
    assert.ok(result.answer.includes('MissingContract'));
    assert.equal(fs.existsSync(path.join(dir, 'nested/output.mjs')), false);
    assert.equal(result.transcript.some((call) => call.tool !== 'read'), false);
  });
});

test('missing input is a failed read, never an empty source or a writing fallback', async () => {
  await fixture(async (dir, entries) => {
    fs.unlinkSync(path.join(dir, 'first.mjs'));
    const result = await drive(planChatStep, dir, prompt, { steps: 12 });
    assert.ok(result.answer.includes('ReadFailed'));
    assert.deepEqual(result.transcript.map((call) => JSON.parse(call.arguments).path), ['nested/output.mjs', 'first.mjs']);
    assert.equal(fs.readFileSync(path.join(dir, 'nested/output.mjs'), 'utf8'), entries['nested/output.mjs']);
  });
});

test('permission errors on the destination retain typed failure rather than absence', async () => {
  const messages = [{ role: 'user', content: prompt }, ...receipt('nested/output.mjs', JSON.stringify({ is_error: true, error: 'EACCES denied' }))];
  const plan = await planModuleFunctionStep(prompt, messages, ['read', 'write']);
  assert.equal(plan.result.disposition, FinalDisposition.Failure);
  assert.equal(plan.result.discovery.reason, 'ReadFailed');
  assert.equal(canDeliverFinal(plan), false);
});

test('missing read capability is an exact typed gap, not a declined route', async () => {
  const plan = await planModuleFunctionStep(prompt, [{ role: 'user', content: prompt }], ['write']);
  assert.equal(plan.result.disposition, FinalDisposition.Gap);
  assert.equal(plan.result.discovery.reason, 'MissingReadTool');
  assert.equal(canDeliverFinal(plan), false);
});

test('old request evidence is not reused for a new discovery request', async () => {
  const messages = [{ role: 'user', content: 'old request' }, ...receipt('nested/output.mjs', 'old bytes'), { role: 'user', content: prompt }];
  const plan = await planModuleFunctionStep(prompt, messages, ['read']);
  assert.equal(plan.kind, 'tool_calls');
  assert.equal(JSON.parse(plan.calls[0].arguments).path, 'nested/output.mjs');
});
